-- Los paraderos que ya no se usan (por ejemplo, los demo) quedan inactivos, no se borran
UPDATE paradero p SET activo = false
 WHERE p.codigo <> ALL (ARRAY['stp_001', 'stp_002', 'stp_003', 'stp_004', 'stp_005', 'stp_006', 'stp_007', 'stp_008', 'stp_009', 'stp_010', 'stp_011', 'stp_012', 'stp_013', 'stp_014', 'stp_015', 'stp_016', 'stp_017', 'stp_018', 'stp_019', 'stp_020', 'stp_021', 'stp_022', 'stp_023', 'stp_024', 'stp_025', 'stp_026', 'stp_027', 'stp_028', 'stp_029', 'stp_030', 'stp_031', 'stp_032', 'stp_033', 'stp_034', 'stp_035', 'stp_036', 'stp_037', 'stp_038', 'stp_039', 'stp_040', 'stp_041', 'stp_042', 'stp_043', 'stp_044', 'stp_045', 'stp_046', 'stp_047', 'stp_048', 'stp_049', 'stp_050', 'stp_051', 'stp_052', 'stp_053', 'stp_054', 'stp_055', 'stp_056', 'stp_057', 'stp_058', 'stp_059', 'stp_060', 'stp_061', 'stp_062', 'stp_063', 'stp_064', 'stp_065', 'stp_066', 'stp_067', 'stp_068', 'stp_069', 'stp_070', 'stp_071', 'stp_072', 'stp_073', 'stp_074', 'stp_075', 'stp_076', 'stp_077', 'stp_078', 'stp_079', 'stp_080', 'stp_081', 'stp_082', 'stp_083', 'stp_084', 'stp_085', 'stp_086', 'stp_087', 'stp_088', 'stp_089', 'stp_090', 'stp_091', 'stp_092'])
   AND NOT EXISTS (SELECT 1 FROM paradero_variante pv WHERE pv.paradero_id = p.id);

-- 4. Paraderos de cada variante. El orden y la distancia los calcula la base
--    (fn_asignar_paraderos_variante) y se comprueba que coincidan con el editor.
DO $$
DECLARE
    v_id uuid;
    v_esperado varchar[] := ARRAY['stp_001', 'stp_002', 'stp_003', 'stp_004', 'stp_005', 'stp_006', 'stp_007', 'stp_008', 'stp_009', 'stp_010', 'stp_011', 'stp_012', 'stp_013', 'stp_014', 'stp_015', 'stp_016', 'stp_017', 'stp_018', 'stp_019', 'stp_020', 'stp_021', 'stp_022', 'stp_023', 'stp_024', 'stp_025', 'stp_026', 'stp_027', 'stp_028', 'stp_029', 'stp_030', 'stp_031', 'stp_032', 'stp_033', 'stp_034', 'stp_035', 'stp_036'];
    v_obtenido varchar[];
BEGIN
    SELECT v.id INTO v_id FROM variante v JOIN linea l ON l.id = v.linea_id
     WHERE l.codigo = 'LB' AND v.ramal = 'MOLLEBAYA' AND v.sentido = 'IDA';
    PERFORM fn_asignar_paraderos_variante(v_id, v_esperado);
    SELECT array_agg(p.codigo ORDER BY pv.orden) INTO v_obtenido
      FROM paradero_variante pv JOIN paradero p ON p.id = pv.paradero_id
     WHERE pv.variante_id = v_id;
    IF v_obtenido IS DISTINCT FROM v_esperado THEN
        RAISE EXCEPTION 'El orden de los paraderos de MOLLEBAYA-IDA no coincide con el editor: %', v_obtenido;
    END IF;
END $$;

